"use strict";(self.webpackChunkportfolio_react_app=self.webpackChunkportfolio_react_app||[]).push([[34],{1987:function(e,t,a){a(2791);t.Z=a.p+"static/media/sharpifyIcon.b6135b85add4a40259079951e0da43a7.svg"},3034:function(e,t,a){a.d(t,{t:function(){return d}});var i=a(9439),o=a(2791),n=a(1112),s=(a(3730),a(184)),r=o.lazy((function(){return a.e(567).then(a.bind(a,567))})),d=function(e){var t=(null===e||void 0===e?void 0:e.amount)||4,a=(0,o.useState)(t),d=(0,i.Z)(a,2),l=d[0],c=d[1],h=e.projects||[];return(0,s.jsx)("div",{children:(0,s.jsx)("div",{className:" flex justify-center",children:(0,s.jsxs)("div",{className:"w-[min(90vw,1200px)] flex flex-col gap-12",children:[h.slice(0,l).map((function(t){return(0,s.jsx)(n.M,{x:0,y:200,children:(0,s.jsx)(r,{project:t,className:e.className})},t.title)})),l<h.length&&(0,s.jsx)("div",{className:"flex justify-center ",children:(0,s.jsxs)("button",{onClick:function(){c((function(e){return e+t}))},className:"rounded-md justify-center w-full text-xl px-4 py-8 mx-4  mb-8 text-center border-2  text-white font-semibold hover:bg-white hover:text-slate-900 md:duration-300 flex items-center",children:[(0,s.jsx)("span",{class:"loading loading-bars loading-md"}),"\xa0VIEW MORE \xa0"," ",(0,s.jsx)("span",{class:"loading loading-bars loading-md"})]})})]})})})}},4272:function(e,t,a){var i,o,n=a(4942),s=a(184),r={procedurallyGeneratedTrees:{vidURL:a(1613),roles:"",data:"May 2023",skills:["Unity","C#"],desc:"Customizable, procedurally generated trees generated from simple rules using Lindenburg Systems. Implemented from scratch in Unity and C#.",title:"Procedural Tree Generator",media:[a(2833),a(280)],details:[{title:"Read the Dev Process",description:"I strongly recommend reading the Dev Process above! It goes into detail about my workflow throughout the project."},{title:"Development",description:'For a while, I have had a huge affinity for procedural generation. A lot of research went into understanding how L-systems work, which is a commonly used to strategy to visualize procedural plant development, fractals, etc. After researching, I implemented a developer-friendly L-System generator and L-System renderer which I hope to soon publish to the Asset Store. I go into much more detail in the "Development Process" pdf above!'},{title:"What I learned",description:"I'm very proud of this projects because I was able to implement this without really looking at any tutorials or code; I purely built this off of research. I became much more familiar with Unity's tools and much more comfortable implementing C#. I refined my probem-solving skills by creating a solution for rendering foliage and animation. "}],buttons:[{label:"Dev Process",url:a(4420)},{label:"Source Code",url:"https://github.com/hungbuiwork/ProceduralTrees/blob/main/Assets/Scripts/LSystemRenderer.cs"}]},toonShader:{vidURL:a(9245),roles:"",date:"NOV 2022 - DEC 2022",skills:["Unity","Shaderlab","HSLS"],desc:"A toon-shader I've been developing that allows customizability of (color, size, smoothness, intensity) of (shadows, specular light, rim light). This customizability allows the user to blend between realistic/cartoony aesthetics. I hope to use this shader in future projects!",title:"Customizable Toon Shader",media:[a(3075),a(1976)],details:[{title:"Read the Dev Process",description:"I strongly recommend reading the Dev Process above! It goes into detail about my workflow throughout the project."},{title:"Background",description:"The end of fall quarter 2023 is nearing, and the final for my Introduction to Computer Graphics is very open-ended -- we were asked to create something in any field of graphics! So, I decided for my project that I wanted to expand on what I learned about vertex and fragment shading! I have a love for cartoon styled graphics, and make games, so why not make a shader which does just that?"},{title:"Development",description:'I implemented diffuse shading, specular light, rim light, outlines, and shadowmapping. I took a very iterative approach, sitting down and taking time to REALLY understand the techniques behind how these affects are attained. I go into much more detail in the "Development Process" pdf above!'},{title:"What I learned",description:"I now have a much better understanding of vertice shaders, fragment shaders, the linear algebra behind shading techniques, how colors blend, world-space vs screen-space and more. "}],buttons:[{label:"Dev Process",url:a(5745)},{label:"Source Code",url:"https://github.com/hungbuiwork/Toon-Shader/blob/main/Assets/ToonShader%20Materials/HBToon.shader"}]},musicalMadness:{vidURL:a(8719),date:"MARCH 2022 - APRIL 2022",roles:"Project Lead, Programmer, 2D Art",size:6,skills:["Unity","C#"],desc:"A music-themed top-down shooter/dungeon exploration video game that I created with UCI's Video Game Development Club. For this project, I developed the procedurally generated dungeon and enemy AI scripts with a focus on maintainability, modularity, and reusability. I played a pivotal role bridging the gap between programming, art, and sound to ensure the creation of an enjoyable, visually appealing, and cohesive gaming experience!",title:"Musical Madness",media:[a(3530),a(3222)],details:[{description:"After being part of several videogame projects in the past, I figured that I developed enough skills and understanding of the game development workflow. So, at the beginning of the spring quarter of 2022, my roommate and I ventured on a journey to pitch our own game to the Video Game Development Club. Inspired by other dungeon crawlers such as Binding of Isaac, I wanted the game to be thrilling, aesthetic, and to keep the gameplay fun and interesting! Also, I wanted to explore procedural generation, which has always intrigued me. So, I along with my roommate took on the challenge of leading the production of Musical Madness!",title:"Background"},{description:"This project focused on creating efficient, well-structured code. After completing relevant courses on software design and algorithms, we applied our knowledge. When designing our procedural generation system, my roommate and I took a careful, iterative approach. We used diagrams, pseudocode, and troubleshooting to understand and address bugs. Later, we improved our dungeon-building algorithm's memory efficiency by using bitwise operations extensively.",title:"Procedural Generation, Enemy AI, and Script Architecture"},{image:a(6493),description:"When it came to designing the overall script architecture, we decided to streamline the implementation of both players and enemies by sharing certain scripts, such as those responsible for managing statistics, combat mechanics, and weapons. The key distinction between them lay in their input methods (keyboard for players, AI for enemies) and their movement patterns. This approach enabled us to maintain a modular codebase and efficiently reuse various components. An exciting benefit of this design was that any entity could seamlessly utilize newly created weapons. This flexibility proved invaluable when implementing the boss character, as it simply inherited behaviors from other enemy types and employed the same arsenal. Furthermore, I implemented optimizations to enhance performance by limiting enemy spawning and updates to the current room or adjacent ones. This optimization significantly improved our game's performance. As the sole developer responsible for the enemy AI, I devised a system that utilized scriptable objects known as 'enemy brains.' These objects comprised a set of predefined values, which in turn generated diverse behaviors. This approach not only reduced the amount of code required but also facilitated the rapid creation of enemies with distinct behaviors. For instance, it allowed us to easily differentiate the strafing behavior of violin enemies from the charging and rolling tactics of drum enemies."},{description:"Leading the project proved to be challenging. I facilitated meetings where we discussed design, game-feel, assigned tasks, and reported progress. I took extra time outside of normal meetings to meet up with the sound team to help tackle challenges!  Ultimately, we developed a game that was enjoyable, cohesive, and full of fun chaos.",title:"Leading the Project"},{description:"I learned so much working on this project, even if it wasn't for the longest time. In terms of leadership, I think I could have improved by having much more efficient meetings, and being more realistic with the scope of the game. Furthermore, I learned a lot about good code design, creating UML diagrams to communicate to other programmers, much more about C#, Unity's scriptable objects, and more. I am so proud of what we created.",title:"What I learned"}],buttons:[{label:"Play",url:"https://hungbui.itch.io/musicalmadness"},{label:"Source Code",url:"https://github.com/hungbuiwork/MusicalMadness"}]},phantomHallowsEve:{roles:"2D & Technical Artist",date:"SEP 2022",skills:["Unity","C#","Asesprite"],desc:"A cozy and spooky puzzle game! For the 2022 Cozy Autumn 2-week Game Jam, I collaborated with a team of 8, creating 2D sprite art, lighting, postprocessing effects, and 2D VFX in Unity.",title:"Phantom Hallow's Eve",buttons:[{label:"Play",url:"https://supriseorb.itch.io/phantom-hallows-eve"},{label:"Source Code",url:"https://github.com/hungbuiwork/Cozy-Autumn-Game-Jam-2022"}]},patientZero:{imgURL:a(1035),size:19,date:"SEP 2021 - APRIL 2022",roles:"Programmer, VFX",skills:["Unity","C#"],desc:'As a Game Programmer for "Patient Zero," an accredited VR bio-educational puzzle game, I collaborate with a skilled team of programmers, artists, writers, and game designers. Our aim is to offer players a captivating sci-fi experience while teaching epidemiology principles. My tasks include fixing UI bugs and implementing essential elements like tooltips and pause menus to enhance the player\'s experience.',title:"Game UI Programmer",company:"Hughes Media & Design Lab",media:[a(701),a(1983)],details:[{title:"Background",description:"It was the fall quarter of 2021, my second year at UCI. I saw that Hughes Media & Design Lab was working on a VR research-based project which simulated a lab in which the player must find out what the disease is. After an interview, I was lucky enough to be able to join the team!"},{title:"What I implemented",description:(0,s.jsxs)("div",{className:" flex flex-col gap-8",children:[(0,s.jsx)("p",{children:'A tooltip/hints 3D UI that pops up when the user picks up a tool. I tried to match the design with the aesthetics of the game. A small optimization I did was to reuse the same object, and simply hide it somewhere off the map when not in use."'}),(0,s.jsx)("p",{children:"I also implemented the game's post-processing to make the world feel more atmospheric and moody. This was especially important as the game is in VR."}),(0,s.jsx)("p",{children:"A pause menu 3D UI that pops up when the pause button is pressed."})]})},{title:"Challenges/Takeaways",description:"With my knowledge of C# at the time, I found working on this project quite challenging. It was a continuation of a project that had been in development for quite some time, and the existing codebase was sometimes hard to work with, as there seemed to be not much thought behind the architecture of the scripts. So, I focused mainly on implementing new UI features, and doing minor bug fixes. Though the codebase was difficult to work with, I took notes of how this could be improved, and in the spring of 2022 created Musical Madness, with an emphasis on good code documentation, task communication, and code architecture!"}],buttons:[{label:"Hughes Lab & Media",url:"https://hughesmedia.bio.uci.edu"},{label:"The Game",url:"https://amily.itch.io/patient-zero"}]},jokeBrowser:{imgURL:a(5616),roles:"",date:"NOV 2022",skills:["AngularJS","Javascript"],desc:"A joke browser I created that displays funny program jokes from JokeAPI, exploring an alternative form of interaction using HandTrackjs. Simply using your camera and hands, you can control the generation, viewing, and favoriting of jokes! Check it out!",title:"Joke Browser & Alternative Interaction",media:[a(9423)],details:[{title:"A bit more",description:'This project marked one of my final assignments in the User Interaction course. It was a highly flexible task, so I decided to develop a web application for browsing jokes. I designed this app using Angular, incorporating a service to fetch jokes from JokeAPI and integrating HandTrackJS for an interactive experience. Users could simply relax, activate their camera, and explore programming jokes. My primary goal was to craft an aesthetically pleasing and user-friendly interface, along with intuitive hand controls. Although the web app is more suitable for non-mobile browsers, you can still give it a try by clicking the "Demo" button above!'}],buttons:[{label:"Source Code",url:"https://github.com/hungbuiwork/JokeWebApp/blob/main/README.md"},{label:"Demo",url:"https://hungbuiwork.github.io/JokeWebApp/"}]},zotDev:{imgURL:a(3590),roles:"Gameplay Programmer & UI Programmer",date:"MAR 2023 - JUN 2023",skills:["Unity","C#"],desc:"Arriving as a freshman college student, you are excited to start the program of your dreams entering the Game Development Major and the Video Game Development Club.",title:"Zot Dev",media:[a(1446)],details:[{title:"To Do",description:"in progress..."}],buttons:[{label:"Source Code",url:"https://github.com/Dg155/UCIGameDevTycoon"},{label:"Play",url:"https://dg155.itch.io/zot-dev"}]},thisWebsite:{vidURL:a(5875),roles:"",date:"DEC 2022",skills:["React","TailwindCSS","Javascript"],desc:"A portfolio website, where I showcase my projects, and art! Developed by myself from scratch over winter break. I learned a lot about react, and responsive design!",title:"This Website !",media:[a(9007)],details:[{title:"Why am I doing this?",description:"I am programming this from scratch. No templates -- just the ReactJS framework, the TailwindCSS framework, and my two hands. I had some extra time this winter break so I decided to redo my portfolio again. My first portfolio was on Adobe Portfolio. My second was plain HTML, and CSS. Though the customizability of plain HTML and CSS was nice, adding new stuff was just repetitive, ugly, and became increasingly harder to read. I wanted to create components that I could customize, and reuse."},{title:"What I am learning",description:"This is currently a work in progress, but I'm learning a lot of things as I work through this. This is my first project using the React framework and Tailwind. I am experimenting a lot with how I want my website to be laid out, and how to implement responsiveness that looks nice on several different devices. So far, I really like react, and love how fast I can iterate with Tailwind(though, I do plan to clean the CSS up in the future)..."}],buttons:[{label:"Source Code",url:"https://github.com/hungbuiwork/portfolio"}]},capstoneArchive:{date:"SEP 2023 - JAN 2024",skills:["ReactJS","TailwindCSS","Typescript","Jira"],roles:["Scrum Master","Full-Stack Developer"],size:5,title:"UCI Capstone Archive v1",desc:"New archival system for UCI Capstone Projects built from scratch, with upload, display, and search features, geared towards attracting to UCI's Capstone program.  UCI faculty assigned us this project and is to be worked on by future students to implement into the official UCI website.",vidURL:a(7993),company:"UCI Informatics Department",details:[{title:"Backlog Creation & Planning",description:"Starting the project from scratch involved having in-depth discussions with stakeholders to grasp their expectations. I took the lead in discussions with faculty members, noting down their requirements and preferences. Before each meeting, I prepared a set of relevant questions, covering use cases, user stories, and trade-offs between project thoroughness and ease of use. These discussions were then compiled into a comprehensive requirements document, serving as a practical guide for implementation."},{title:"Use cases",description:"Adopting a software engineering mindset involved placing myself in the shoes of potential users. Deliberations revolved around crucial decisions, such as prioritizing the display of company name or project image. Understanding the needs of industry partners, faculty members,  and students, I delved into questions regarding the amount of information preferred in each project. This perspective played a pivotal role in shaping the user-centric aspects of the project."},{title:"Project Leading",description:"Navigating the challenges of project leadership provided invaluable learning experiences. Assessing evolving requirements, organizing them into a backlog, and strategically assigning tasks based on skills and availability were crucial responsibilities. Extensive planning was employed to mitigate merge conflicts and task overlap, emphasizing the importance of robust communication. Despite the complexities, the team successfully implemented numerous features within a single quarter."},{title:"Implementation",description:"Contributing to the project's development, I personally implemented key features such as the responsive project search page, project component, routing, individual project page, upload form CSS, and the suggested projects tab for searching adjacent projects. Breaking down the front-end and back-end into organized components facilitated a cohesive and efficient coding process."},{title:"Learning Points",description:"Overall, I found it important to learn various aspects. Regarding the agile process, I found it important to plan early, ask a lot of clarifying questions, assess your team's skills, and approximate the time of tasks. Concerning the software design process, I found it important to make use of user stories, plan out the structure of the code before implementing, and talk to multiple stakeholders, as some had differing opinions. In terms of implementation, I found it important to break code down into components and document what you write."}],buttons:[{label:"Live Demo",url:"https://hungbuiwork.github.io/capstone-archive/"},{label:"Requirements Document",url:"https://docs.google.com/document/d/10vIFHweKmLg4ncYmA97udMbRj0zmnqgtXvflhPrLlLE/edit?usp=sharing"}]},wartorn:{date:"SEP 2023 - MAR 2024",skills:["Unreal","VFX","Agile"],vidURL:a(4639),roles:["Art Lead, Lighting, Postprocess, Shader Artist"],title:"Wartorn",size:19,desc:"A 3D narrative game where players take on the role of a young girl navigating the aftermath of a war attack. Through the use of lighting, visual effects, and dialogue, our game tells a story that explores themes of early maturing.",media:[a(4639),a(9560),a(310),a(8147)],details:[{title:"Material Shaders",description:"I created, in Unreal's Material's Editor, a custom material shader that blends toon-shading with the default texture, with parameters to adjust over blending, shadow and highlight color, as well as some degree of atmospheric fog. These gave me a lot of control over the color scheme and atmosphere created in each level. By adjusting these levels, I was able to start with a more colorful, warm, cheerful aesthetic that became darker, and more realistic as time continue -- reflecting the game theme of early maturation and perception."},{description:"I also created a fog shader, with parameters to adjust strength, color, which combined with noise, was able to achieve some movement that felt natural and realistic. I used the fog shader in vastly different ways -- to conceal forbidden areas/out-of-bounds, to fake god rays and dust, and to convey air pollution post-attack."},{description:"With a mix of my shaders, and tweaking Unreal's built-in postprocessing pipeline, I adjusted levels and lighting to convey the feeling that the MC was supposed to feel. I utilized the contrast between cool/warm colors to convey safety and danger, darkness to convey loneliness, and saturation to convey homeliness. ",title:"Postprocessing"},{title:"Leading the art team",description:"Apart from my contributions directly into the game, I led a 4-person art department, utilizing Jira and google spreadsheets to assign and track progress of each for each sprint (we used an Agile approach). I acted as a quality check to all the art imported. One thing I learned leading a department, is that establishing a consistent and concise workflow makes work so much more efficient, so I established a document with the producer during the second half of production that streamlined everyone's workflow. Proud of the outcome!"}],buttons:[{label:"Itch.io Page",url:"https://dnajerab.itch.io/wartorn"}]},Partyify:{data:"APRIL 2024",skills:["React","TailwindCSS","SpotifyAPI"],title:"Party-ify (Spotify App)",desc:"Used at parties and gatherings, Partyify allows people to queue music to the party's playlist with just the scan of a QRCode. Only the host needs a spotify account.",vidURL:a(2374),buttons:[{label:"Try it out",url:"https://hungbuiwork.github.io/PartySpotify/"}],details:[{title:"Why make this?",description:"I noticed at parties and gatherings in Uni, that usually one person has control of the entire playlist. This is because Spotify's implementation of shared song sessions has many limitations: each user needs a spotify account, and the number of users in the sessions stays limited, and setup takes time, and rejoining/leaving a session is tedious"},{},{title:"Learning the SpotifyAPI",description:"I spent time going through the Spotify API documentation, reading and learning about how it works. I implemented Spotify OAuth to make sure everything was secure and users could interact smoothly. With React.js, I set up the routing so users could go directly to their Spotify accounts using specific URLs, and turned those URLs into QR codes using a library. Using the info passed through the URL routing, I made fetch calls to the Spotify API accordingly to implement queuing, searching, playing, seeking, and skipping to next/previous songs."},{title:"Designing UI",description:"I created a user interface that's sleek and adaptable, catering to both large screens like TVs and smaller mobile displays, perfect for in-car use. Each page is crafted with simplicity in mind, featuring intuitive controls and a clear visual hierarchy for easy navigation. By blending modern design elements, I achieved a fresh look while staying true to Spotify's recognizable color palette and branding."},{title:"Testing, Improving",description:"Right now, I'm trying out the app with friends and at parties, getting their thoughts and feedback. They're helping me see what works and what needs tweaking, like how well the recommendation system is doing. So far, the app has been very useful, and I plan to make iterative improvements as time goes on!"}]},whatCares:{image:a(6965),date:"JULY 2023 - AUG 2024",skills:["ReactJS","TailwindCSS"],desc:"I am currently developing an informative website for WhatCares, which stands for World Health Access Team, a nonprofit organization comprising medical professionals actively conducting medical missions worldwide. The primary focus of this ongoing project is to create a website specifically tailored to engage potential donors and supporters. The site is not deployed as of yet, but soon check again soon!",title:"Freelance Website Developer",company:"WhatCares nonprofit"},gdim:{imgURL:a(5341),date:"FEB 2023 - JUN 2023",skills:["HTML","CSS","Figma"],desc:"In my role as a Website Design Intern for UCI's Game Development & Interactive Media program, I collaborate closely with esteemed faculty members -- tasked with crafting user-friendly informational user interfaces and developing websites tailored to convey class-related information and a website to showcase student-made games.",title:"Website Design Intern",company:"UCI Game Design & Interactive Media",media:[a(3475)],details:[{title:"",description:"In my work, I collaborate with faculty to discuss tasks and projects, incorporating design feedback and iterating on designs as needed. For instance, I created a flyer in Figma for the Game Developer's Conference 2023 to boost awareness of the GDIM (Game Development & Interactive Media) major. I also create HTML and CSS syllabus websites when needed"}]},sharpify:(i={imgURL:a(1987).Z,company:"Sharpify.AI",date:"AUG 2024 - PRESENT",skills:["ReactJS","Python","FastAPI","PostgreSQL","TailwindCSS"],desc:"Sharpify is a financial tech startup, which provides a secure platform for users to make predictions on stocks and cryptos, which are then validated, scored by accuracy, and ranked. I developed and implemented multiple core backend and frontend features, working closely with the CEO and a small team of engineers to create a secure, reliable, and user-friendly platform.",title:"Full Stack Engineer Intern"},(0,n.Z)(i,"company","SharpifyAI"),(0,n.Z)(i,"buttons",[{label:"Sharpify.AI",url:"https://sharpify.ai/"}]),i),kernvascular:(o={imgURL:a(7538),date:"MAY 2025 - SEP 2025",company:"Kern Vascular Center",skills:["NextJS","Typescript","PostgreSQL","TailwindCSS","OpenAI GPT API","Microsoft Azure Cognitive Services (Speech)"],desc:"At Kern Vascular, I worked as a Software Engineer focused on AI integrations, building custom tools to optimize clinical workflows. My role blended IT and full-stack development, identifying inefficiencies in patient care and office operations, then delivering solutions that improved both staff efficiency and patient satisfaction.",title:"Software Engineer \u2013 AI Integrations (Contract)"},(0,n.Z)(o,"company","Kern Vascular"),(0,n.Z)(o,"buttons",[{label:"Company Website",url:"https://kernvascular.com/"},{label:"AI Scribe",url:"https://hbai-scribe.vercel.app/about"}]),(0,n.Z)(o,"media",[a(3129),a(8635),a(653),a(7546)]),(0,n.Z)(o,"details",[{title:"Responsibilities",description:"Worked directly with clinicians and staff to identify bottlenecks and iteratively build solutions for real-world effectiveness."},{title:"AI-Powered Clinical Documentation",description:"Developed a full-stack application that listens to doctor\u2013patient interactions, auto-generates documentation, proposes differential diagnoses, and suggests follow-up questions."},{title:"Patient Queue Coordination",description:"Built a cross-team patient queue service that improved collaboration, reduced wait times, and enhanced patient satisfaction."},{title:"Phone System Redesign",description:"Triaged, re-engineered, and fixed the office phone system to resolve accessibility issues and significantly improve call handling rates."},{title:"Agile Development & QA",description:"Collaborated in an iterative workflow, shadowing patient interactions, testing features, and refining tools to meet operational needs."}]),o),everlaw:{imgURL:a(5093),date:"SEP 2025 - PRESENT",skills:["ReactJS","Typescript","Java","AWS"],desc:"My current job! Full stack engineering building eDiscovery tools for legal teams. Working closely with product managers and designers to build features that help lawyers do their jobs more efficiently.",title:"Software Engineer ",company:"Everlaw - Oakland Office"}};t.Z=r},3730:function(e,t,a){a.d(t,{Mf:function(){return n},c8:function(){return o},fc:function(){return s}});var i=a(4272),o=[i.Z.Partyify,i.Z.procedurallyGeneratedTrees,i.Z.capstoneArchive,i.Z.musicalMadness,i.Z.toonShader,i.Z.wartorn,i.Z.jokeBrowser,i.Z.zotDev,i.Z.thisWebsite],n=[i.Z.Partyify,i.Z.capstoneArchive,i.Z.musicalMadness,i.Z.procedurallyGeneratedTrees,i.Z.jokeBrowser,i.Z.toonShader,i.Z.wartorn],s=[i.Z.wartorn,i.Z.musicalMadness,i.Z.procedurallyGeneratedTrees,i.Z.toonShader,i.Z.zotDev,i.Z.Partyify,i.Z.capstoneArchive,i.Z.jokeBrowser]},4420:function(e,t,a){e.exports=a.p+"static/media/ProceduralTrees.891308b957eb6e5c6e7d.pdf"},5745:function(e,t,a){e.exports=a.p+"static/media/Toon_Shader.1956bd6e276b67c37d7e.pdf"},280:function(e,t,a){e.exports=a.p+"static/media/Proceduraltreedemo.50235f0a1ee242a02c91.mp4"},6965:function(e,t,a){e.exports=a.p+"static/media/logo.feaaf7395f9d128000e6.ico"},8719:function(e,t,a){e.exports=a.p+"static/media/musicalmadness.033fd2daf61007e024d2.m4v"},1983:function(e,t,a){e.exports=a.p+"static/media/patientZero_tooltip.fd453136717b970a3934.mp4"},653:function(e,t,a){e.exports=a.p+"static/media/Diagnosis.e96da189572b60516327.webm"},3129:function(e,t,a){e.exports=a.p+"static/media/Dictate.4ac967e191d34646ec61.webm"},8635:function(e,t,a){e.exports=a.p+"static/media/Generate.b4df9baf066176c2bf8d.webm"},5875:function(e,t,a){e.exports=a.p+"static/media/website-art.851c192a704222663928.mp4"},3475:function(e,t,a){e.exports=a.p+"static/media/GDC-Flyer.2e027c8dddf68a1fc4cd.png"},310:function(e,t,a){e.exports=a.p+"static/media/Wartorn1.78fac8033b56619a98e2.png"},8147:function(e,t,a){e.exports=a.p+"static/media/WartornLead.40f2dfd1a953d891eac9.png"},9560:function(e,t,a){e.exports=a.p+"static/media/WartornShader2.81990a75f33765521e38.png"},5341:function(e){e.exports="data:image/jpeg;base64,"},1035:function(e,t,a){e.exports=a.p+"static/media/hughestmediadesignlabIcon.f5fd5a19bf54b273b2a9.png"},9423:function(e,t,a){e.exports=a.p+"static/media/jokeBrowser_ui.6a9dd313863bc351b44f.jpeg"},7538:function(e,t,a){e.exports=a.p+"static/media/kernvascularIcon.144d107bf2f7aa0f7b48.png"},6493:function(e,t,a){e.exports=a.p+"static/media/musicalMadness_architecture.0945f32ca83fe017869b.jpeg"},3222:function(e,t,a){e.exports=a.p+"static/media/musicalMadness_map.29532625c9c6d4d1dd7c.jpeg"},7546:function(e,t,a){e.exports=a.p+"static/media/patientQueue.14862ed674f9ef75acc2.png"},701:function(e,t,a){e.exports=a.p+"static/media/patientzero.20c6918c4cf497225467.jpeg"},2833:function(e,t,a){e.exports=a.p+"static/media/proceduraltree2.a0ff7203462e8bc6c99b.png"},1976:function(e,t,a){e.exports=a.p+"static/media/toonShader_house.3b6e518b787d68c63975.jpeg"},3075:function(e,t,a){e.exports=a.p+"static/media/toonShader_scene.15f2bdf68e52193d32f6.jpeg"},9007:function(e,t,a){e.exports=a.p+"static/media/website.73c18bb57cf2c6f9c7e7.gif"},1446:function(e,t,a){e.exports=a.p+"static/media/zotdev_sleep.20e9bca856a163db7077.png"},3590:function(e,t,a){e.exports=a.p+"static/media/zotdev_thumbnail.0391f114b88c15abcd8d.png"}}]);
